"use strict";

// A read-only view of curated JSON generated by tools/build_public_index.py.
// No analytics, tracking scripts, credentials, uploads or external dependencies.
const SOURCE_LABELS = {
  mac_dimension_sweep: "Mac · n=1…10 (transcribed)",
  mac_n20: "Mac · n=20 (transcribed)",
  development_dimension_pilot: "Development pilot",
  development_n20: "Development · n=20"
};
const WALK_LABELS = {
  ball: "Ball Walk",
  dikin: "Dikin Walk",
  coordinate_hit_run: "Coordinate Hit-and-Run",
  random_hit_run: "Random Hit-and-Run",
  john: "John's Walk"
};
const FIELDS = ["dimension", "walk", "language", "stage", "source", "steps", "chains", "seed"];
let records = [];
let filtered = [];

const byId = (id) => document.getElementById(id);
function present(value) {
  return value !== null && value !== undefined && value !== "";
}
function cell(tr, text, className = "") {
  const td = document.createElement("td");
  td.textContent = text;
  if (className) td.className = className;
  tr.appendChild(td);
  return td;
}
function numeric(value, digits = 3) {
  if (!present(value) || !Number.isFinite(Number(value))) return "—";
  return Number(value).toLocaleString("en-US", {maximumFractionDigits: digits});
}
function estimate(row) {
  if (![row.checkpoint, row.chains, row.us_per_step].every(present)) return null;
  return row.checkpoint * row.chains * row.us_per_step / 1000000;
}
function matches(row) {
  for (const field of FIELDS) {
    const v = byId(field).value.trim();
    if (!v) continue;
    const key = field === "dimension" ? "n" : field;
    if (["dimension", "steps", "chains", "seed"].includes(field)) {
      if (!present(row[key]) || Number(row[key]) !== Number(v)) return false;
    } else if (String(row[key]) !== v) return false;
  }
  return true;
}
function render() {
  filtered = records.filter(matches);
  const body = byId("rows");
  body.replaceChildren();
  byId("count").textContent = filtered.length.toLocaleString() + " of " + records.length.toLocaleString() + " observations shown";
  byId("download").disabled = filtered.length === 0;
  if (!filtered.length) {
    const tr = document.createElement("tr");
    cell(tr, "No matching observations. Clear some filters or try a documented dimension.", "muted").colSpan = 10;
    body.appendChild(tr);
    return;
  }
  // Limit DOM work for large future public archives; CSV export includes all matches.
  for (const row of filtered.slice(0, 150)) {
    const tr = document.createElement("tr");
    cell(tr, String(row.n));
    cell(tr, WALK_LABELS[row.walk] || row.walk);
    cell(tr, row.language === "cpp" ? "C++17" : "Python");
    const stage = cell(tr, row.stage);
    stage.className = "pill " + row.stage;
    const source = cell(tr, SOURCE_LABELS[row.source] || row.source, "source");
    source.title = row.notes || "";
    cell(tr, numeric(row.checkpoint, 0), present(row.checkpoint) ? "" : "muted");
    cell(tr, numeric(row.us_per_step, 4));
    cell(tr, numeric(row.runtime_s, 4));
    cell(tr, numeric(estimate(row), 5));
    const linkCell = document.createElement("td");
    const link = document.createElement("a");
    link.href = "https://github.com/Souravfrp/Experiments-on-Random-Walks/blob/main/" + row.source_file;
    link.textContent = "Source ↗";
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.title = row.notes || "Original curated numerical table";
    linkCell.appendChild(link);
    tr.appendChild(linkCell);
    body.appendChild(tr);
  }
  if (filtered.length > 150) {
    const tr = document.createElement("tr");
    cell(tr, "Showing the first 150 rows. Filter further or export all matching rows as CSV.", "muted").colSpan = 10;
    body.appendChild(tr);
  }
}
function downloadCsv() {
  const cols = ["id", "source", "source_file", "walk", "n", "language", "stage", "steps", "chains",
                "seed", "repeats", "threads", "checkpoint", "us_per_step", "runtime_s", "exact_tv_10pct_steps", "notes"];
  function escapeCsv(item) {
    const t = present(item) ? String(item) : "";
    return '"' + t.replace(/"/g, '""') + '"';
  }
  const csv = [cols.join(","), ...filtered.map(row => cols.map(c => escapeCsv(row[c])).join(","))].join("\r\n");
  const objectUrl = URL.createObjectURL(new Blob([csv], {type: "text/csv;charset=utf-8"}));
  const a = document.createElement("a");
  a.href = objectUrl;
  a.download = "random_walk_experiments_filtered.csv";
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(objectUrl), 0);
}
document.addEventListener("DOMContentLoaded", async () => {
  for (const field of FIELDS) {
    byId(field).addEventListener("input", render);
    byId(field).addEventListener("change", render);
  }
  byId("clear").addEventListener("click", () => {
    byId("filters").reset();
    render();
  });
  byId("download").addEventListener("click", downloadCsv);
  byId("download").disabled = true;
  try {
    const response = await fetch("./data/experiments.json", {cache: "no-cache"});
    if (!response.ok) throw new Error("HTTP " + response.status);
    const payload = await response.json();
    if (payload.schema_version !== 1 || !Array.isArray(payload.records)) throw new Error("Unsupported archive schema");
    records = payload.records;
    byId("stat-records").textContent = numeric(records.length, 0);
    const dimensions = [...new Set(records.map(r => r.n))].sort((a, b) => a - b);
    byId("stat-dimensions").textContent = dimensions.length.toLocaleString();
    render();
  } catch (err) {
    byId("count").textContent = "Unable to load the public index. Please check the Pages deployment.";
    const body = byId("rows");
    body.replaceChildren();
    const tr = document.createElement("tr");
    cell(tr, "Archive data could not be loaded: " + err.message).colSpan = 10;
    body.appendChild(tr);
  }
});
